// Parser de mensajes entrantes de Evolution API (Multi-Device QR)
const body = $input.first().json.body || $input.first().json;
const data = body.data || body;

// 1. FILTRO ANTICOLISIÓN: Ignorar mensajes enviados por el software del lab o secretaria
if (!data || data.key?.fromMe) {
  return [];
}

const senderRemoteJid = data.key?.remoteJid || '';

// Ignorar grupos o historias
if (!senderRemoteJid || senderRemoteJid.includes('@g.us') || senderRemoteJid.includes('status@broadcast')) {
  return [];
}

const senderPhone = senderRemoteJid.replace('@s.whatsapp.net', '');
const senderName = data.pushName || 'Paciente';
const messageType = data.messageType || 'conversation';

let userText = '';
let base64Media = null;
let isImage = false;

if (data.message?.conversation) {
  userText = data.message.conversation;
} else if (data.message?.extendedTextMessage?.text) {
  userText = data.message.extendedTextMessage.text;
} else if (data.message?.imageMessage) {
  isImage = true;
  userText = data.message.imageMessage.caption || '[Foto de récipe/orden médica adjunta]';
  base64Media = data.base64 || null;
} else if (data.message?.audioMessage) {
  userText = '[Nota de voz del paciente]';
}

if (!userText && !isImage) {
  return [];
}

// 2. VISION OCR MULTIMODAL CON GEMINI PARA RÉCIPES MÉDICOS
if (isImage && base64Media) {
  try {
    const cleanBase64 = base64Media.includes(',') ? base64Media.split(',')[1] : base64Media;
    const ocrRes = await fetch('https://generativelanguage.googleapis.com/v1beta/models/gemini-3.1-flash-lite:generateContent?key=' + Buffer.from('QVEuQWI4Uk42SkxfM2ZQUjVyN1N1cXQzc1hGdWRjZjJZOFozNEVzRzdnV05nN3pXM1p1QXc=', 'base64').toString() + '', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        contents: [{
          parts: [
            { text: "Lee con atención esta foto de orden médica, récipe o solicitud clínica manuscrita. Identifica y lista con precisión los nombres de todos los exámenes de laboratorio solicitados por el médico para que el bot pueda cotizarlos y dar ayunos." },
            { inline_data: { mime_type: "image/jpeg", data: cleanBase64 } }
          ]
        }]
      })
    });
    const ocrData = await ocrRes.json();
    const extractedText = ocrData.candidates?.[0]?.content?.parts?.[0]?.text || '';
    if (extractedText) {
      userText = '[Foto de récipe médico enviada por el paciente]. Contenido identificado de la orden:\n' + extractedText + (userText && userText !== '[Foto de récipe/orden médica adjunta]' ? '\nComentario del paciente: ' + userText : '');
    }
  } catch (e) {
    console.warn('OCR error:', e);
  }
}

return [{
  json: {
    senderRemoteJid,
    senderPhone,
    senderName,
    userText,
    isImage,
    base64Media,
    instance: body.instance || 'gonzalez-prato'
  }
}];

try {
  const res = await fetch('https://petcqaixzetwsduscvtx.supabase.co/rest/v1/examenes?activo=eq.true&select=categoria,nombre_examen,sinonimos,costo_usd,requisitos_preanaliticos,tipo_muestra', {
    headers: {
      'apikey': 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InBldGNxYWl4emV0d3NkdXNjdnR4Iiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODk1OTAxNjMsImV4cCI6MjEwNTE2NjE2M30.4vDNJ3nBMi0TQg71KZUpyJdcBWr5zyTDKR92xA4obgM'
    }
  });
  const list = await res.json();
  return JSON.stringify({
    status: 'success',
    laboratorio: 'GONZALEZ-PRATO',
    nota: 'Tarifario oficial dinamico en tiempo real desde Supabase (USD).',
    tarifario_oficial_usd: list.map(d => ({
      categoria: d.categoria,
      examen: d.nombre_examen,
      sinonimos: d.sinonimos || [],
      precio_usd: Number(d.costo_usd),
      ayuno: d.requisitos_preanaliticos,
      muestra: d.tipo_muestra
    }))
  });
} catch (e) {
  return JSON.stringify({ status: 'error', message: e.message });
}

const senderPhone = $('Parsear Mensaje Evolution API').item.json.senderPhone;
try {
  await fetch('https://petcqaixzetwsduscvtx.supabase.co/rest/v1/pacientes_leads?whatsapp_id=eq.' + senderPhone, {
    method: 'PATCH',
    headers: {
      'Content-Type': 'application/json',
      'apikey': 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InBldGNxYWl4emV0d3NkdXNjdnR4Iiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODk1OTAxNjMsImV4cCI6MjEwNTE2NjE2M30.4vDNJ3nBMi0TQg71KZUpyJdcBWr5zyTDKR92xA4obgM',
      'Authorization': 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InBldGNxYWl4emV0d3NkdXNjdnR4Iiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODk1OTAxNjMsImV4cCI6MjEwNTE2NjE2M30.4vDNJ3nBMi0TQg71KZUpyJdcBWr5zyTDKR92xA4obgM'
    },
    body: JSON.stringify({
      estado_atencion: 'ESCALADO_HUMANO',
      updated_at: new Date().toISOString()
    })
  });
} catch (err) {
  console.warn('Error patching handover to Supabase:', err);
}

return JSON.stringify({
  status: 'handover_triggered',
  alert: 'ALARMA_RECEPCION_ACTIVADA',
  mensaje: 'Se ha activado la alarma sonora en recepcion para atencion inmediata por la secretaria.'
});
